import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"智能评论","description":"灵萌智能评论配置：用户侧智能回复与摘要、自动发评、机器人与计划任务，依赖 AI 中台场景路由。","frontmatter":{"title":"智能评论","description":"灵萌智能评论配置：用户侧智能回复与摘要、自动发评、机器人与计划任务，依赖 AI 中台场景路由。"},"headers":[],"relativePath":"features/ai-comment.md","filePath":"features/ai-comment.md","lastUpdated":1785051348000}'),d={name:"features/ai-comment.md"};function l(n,t,i,s,h,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="智能评论" tabindex="-1">智能评论 <a class="header-anchor" href="#智能评论" aria-label="Permalink to &quot;智能评论&quot;">​</a></h1><p>路径：<strong>评论运营 → 智能评论配置</strong>（以及 <strong>智能评论机器人</strong>、<strong>计划与任务</strong>）</p><p>两块能力：</p><ol><li><strong>用户辅助</strong>：智能回复建议、评论摘要（帮用户写评论）</li><li><strong>自动发评</strong>：按策略用机器人账号自动评论，提升氛围（需谨慎运营）</li></ol><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ol><li><strong>AI 中台</strong> 已开通，并完成：供应商 → 模型 → <strong>场景路由</strong>（智能评论相关场景已绑定模型）<br> 见 <a href="/features/ai">AI 中台</a></li><li>评论 / AI 相关模块在 <strong>我的模块</strong> 中已解锁</li><li>建议先在 <strong>区域管理 → 笔记配置</strong> 中确认允许评论</li></ol><hr><h2 id="一、智能评论配置-核心" tabindex="-1">一、智能评论配置（核心） <a class="header-anchor" href="#一、智能评论配置-核心" aria-label="Permalink to &quot;一、智能评论配置（核心）&quot;">​</a></h2><p>路径：<strong>评论运营 → 智能评论配置</strong></p><h3 id="选区域" tabindex="-1">选区域 <a class="header-anchor" href="#选区域" aria-label="Permalink to &quot;选区域&quot;">​</a></h3><ul><li><strong>平台默认</strong>（区域编号 0）：未单独配置的区域继承这里</li><li><strong>具体区域</strong>：可覆盖平台默认</li></ul><p>页面会提示当前是「继承平台默认后的生效值」还是「已保存区域独立配置」。</p><h3 id="编辑配置" tabindex="-1">编辑配置 <a class="header-anchor" href="#编辑配置" aria-label="Permalink to &quot;编辑配置&quot;">​</a></h3><p>点 <strong>编辑配置</strong>，主要分组：</p><h4 id="用户辅助" tabindex="-1">用户辅助 <a class="header-anchor" href="#用户辅助" aria-label="Permalink to &quot;用户辅助&quot;">​</a></h4><table tabindex="0"><thead><tr><th>开关</th><th>说明</th></tr></thead><tbody><tr><td><strong>智能评论总开关</strong></td><td>总闸，关掉则用户侧 AI 评论能力不可用</td></tr><tr><td><strong>智能回复</strong></td><td>为用户生成回复建议</td></tr><tr><td><strong>评论摘要</strong></td><td>生成评论摘要类能力</td></tr><tr><td><strong>运营备注</strong></td><td>仅后台可见</td></tr></tbody></table><h4 id="自动发评-可选-影响较大" tabindex="-1">自动发评（可选，影响较大） <a class="header-anchor" href="#自动发评-可选-影响较大" aria-label="Permalink to &quot;自动发评（可选，影响较大）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>配置方向</th><th>说明</th></tr></thead><tbody><tr><td>自动发评总开关</td><td>是否启用机器人自动评论</td></tr><tr><td>目标机器人数 / 昵称前缀 / 头像 URL 池</td><td>机器人身份池</td></tr><tr><td>笔记发布后触发、热度联动、闲置自动发评</td><td>触发时机</td></tr><tr><td>热度阈值、目标条数、延迟</td><td>节奏控制</td></tr><tr><td>真人评论后放慢</td><td>避免刷屏感</td></tr><tr><td>区域日限额、最低置信度</td><td>成本与质量</td></tr></tbody></table><p>改完保存。高级策略也可从 <strong>区域管理 → 笔记配置 → 评论设置</strong> 中的快捷入口跳转过来。</p><hr><h2 id="二、机器人与计划" tabindex="-1">二、机器人与计划 <a class="header-anchor" href="#二、机器人与计划" aria-label="Permalink to &quot;二、机器人与计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>评论运营 → 智能评论机器人</strong></td><td>维护自动发评用的机器人账号/人设</td></tr><tr><td><strong>评论运营 → 计划与任务</strong></td><td>查看或调度自动发评相关任务（以页面为准）</td></tr></tbody></table><p>建议顺序：先配好 <strong>智能评论配置</strong> → 再建机器人 → 再开自动发评与计划。</p><hr><h2 id="与笔记配置的关系" tabindex="-1">与笔记配置的关系 <a class="header-anchor" href="#与笔记配置的关系" aria-label="Permalink to &quot;与笔记配置的关系&quot;">​</a></h2><p><strong>区域管理 → 笔记配置 → 评论设置</strong> 里也有智能评论相关快捷开关（总开关、智能回复、评论摘要）。<br> 两边需保持一致理解：</p><ul><li>笔记配置：区域内容规则总览</li><li>智能评论配置：自动发评、机器人池等高级项的主阵地</li></ul><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>AI 中台场景路由已指向可用模型；<strong>AI 对话</strong> 能测通</li><li>打开某区域智能评论总开关与「智能回复」</li><li>客户端进入评论框，出现 AI 辅助入口并能生成内容</li><li>若开自动发评：发一篇测试笔记，一段时间后出现机器人评论；在 <strong>用量与日志</strong> 可见调用</li><li>配额打满时会失败：到 <strong>AI中台 → 配额规则 / 用量与日志</strong> 排查</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>开关开了无效果</td><td>场景路由未配；总开关未开；区域继承了关闭的平台默认</td></tr><tr><td>提示无可用模型 / 调用失败</td><td>见 <a href="/features/ai">AI 中台</a> 常见问题</td></tr><tr><td>自动评论太多招反感</td><td>降低目标条数、提高延迟、开启「真人评论后放慢」、设日限额</td></tr><tr><td>风险审核拦截</td><td><strong>AI中台 → 风险审核</strong> 查看记录，调整 Prompt 或策略</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ai">AI 中台</a></li><li><a href="/features/circle-note">圈子与笔记</a></li><li><a href="/features/circle-note">统一评论</a>（评论列表入口：评论运营 → 统一评论管理）</li></ul>',37)])])}const u=r(d,[["render",l]]);export{c as __pageData,u as default};
